"""Readable selected-cell matrix; measured timing never implies broad support."""
import json
from pathlib import Path
b=Path(__file__).resolve().parent;e=b.parents[1]/'evidence'/b.name
functional=[('runtime-probe-repaired','7B AWQ, short'),('runtime-probe-qwen15','1.5B, short'),('runtime-probe-opt125-complete','OPT125M MHA'),('runtime-probe-minimal','7B, bounded audit-off'),('runtime-probe-abandon-effective','7B, abandoned advice'),('runtime-probe-long','7B AWQ, long'),('runtime-probe-qwen15-long','1.5B, long'),('runtime-probe-graphs','7B AWQ, long graphs')]
lines=['# Selected support and qualification matrix','','Every observed cell uses the local2080Ti/WSL2 host, pinned0.26.1 runtime, FP16 KV, TP1 and one full-attention KV group. AWQ quantizes model weights. Raw int8 CPU backing stores unquantized KV bytes. Separate model, memory and execution cells do not qualify their cross-product.','','| Selected functional cell | Context / execution | GPU / CPU KV MiB | Classification |','| --- | --- | --- | --- |']
for name,label in functional:
 r=json.loads((b/name/'result.json').read_text());p=r['plan'];d=json.loads((b/(name+'-functional-decision.json')).read_text());a=json.loads((b/(name+'-allocation-receipts.json')).read_text())['cases'][0]['observations'][0];g=a['observation'];cpu=a['actual_cpu_bytes']/2**20;gpu=p['gpu_blocks']*g['kv_bytes_per_chunk']/2**20
 lines.append(f"| [{label}](../../output/{b.name}/{name}-functional-decision.json) | {p['max_model_len']} / {p['execution']} | {gpu:g} / {cpu:g} | {'Functional only: all six waves and operational/allocation checks pass' if d['selected_functional_cell_passed'] else 'Unqualified: diagnose failed receipt'} |")
lines.extend(['','Functional acceptance requires actual CPU restoration (or intentional no-restore after abandonment), a fresh reference that recomputes its entire prompt with zero external hits, exact greedy IDs, strict protocol checks, native abort/drain/recovery, pinned shared backing and owned cleanup. Graphs additionally require actual timed FULL dispatch evidence. This is not direct KV byte comparison, all-position support, production reliability or application speed.','','| Selected workflow cell | Completed timing outcome versus plain ARC | Classification |','| --- | --- | --- |'])
for name in ('stage4-graphs','stage4-qwen15-performance','stage4-qwen15-cohost','stage4-minimal-performance'):
 sp=b/(name+'-summary.json');rp=b/name/'result.json'
 if not sp.exists():outcome='Pending or running';classification='Untested for performance until completed'
 else:
  s=json.loads(sp.read_text());r=json.loads(rp.read_text());c=s['comparisons']['wait_vs_arc'];v=c['candidate_batch_time_reduction_pct'];ci=c['candidate_batch_time_reduction_95ci_pct'];outcome=(f'{v:+.2f}% batch time saved' if v is not None else 'No eligible paired estimate')+(' ('+f'{ci[0]:+.2f} to {ci[1]:+.2f}% conditional95% interval'+')' if ci else '')
  classification=f"{r['status']}: complete measurements do not establish useful-answer parity or broad model qualification"
 lines.append(f'| [{name}](../../output/{b.name}/{name}-summary.json) | {outcome} | {classification} |')
lines.extend(['','The final machine-readable [matrix](../../output/'+b.name+'/support-matrix.json) preserves every original attempt and replacement. Initial protocol-adapter failure, incomplete OPT snapshot and two abandonment-activity declaration mistakes remain visible. Functional diagnostic spans include extra candidate RPCs and are not matched application timing.','','The public and isolated standalone clients pass positive CPU-ready refresh, actual tool execution, pinning, drain and cleanup. Isolation is author-run on the same host, with a separately captured dependency closure and disclosed transitive differences; it does not reproduce benchmark timing or substitute for independent human reproduction.','','| Runtime/environment boundary | Classification |','| --- | --- |','| Pinned0.26.1rc1.dev75+gdc1be7903 plus retained native patches | Supported for the specifically observed local functional cells; performance claims remain conditional on their measured workloads |','| Newer published retention runtime0.1.dev1+g7966f717d.precompiled | Unsupported: actual extension import fails and native publication/scheduler/allocation APIs differ |','| Other GPUs, native Linux, BF16, distributed execution, hybrid/sliding-window/multiple KV groups | Untested |','','Finite churn/recovery exposure cannot establish an unbounded-session limit or production failure rate. See [regressions](REGRESSIONS.md), [quality](QUALITY.md) and the stage reports.'])
(e/'SUPPORT_MATRIX.md').write_text('\n'.join(lines)+'\n');print('Wrote observed functional matrix and explicit workflow status')
